package log

import (
	"gitea.dev/modules/slog"
)

// These flags define which text to prefix to each log entry generated by the
// legacy text format.
const (
	Ldate          = slog.Ldate
	Ltime          = slog.Ltime
	Lmicroseconds  = slog.Lmicroseconds
	Llongfile      = slog.Llongfile
	Lshortfile     = slog.Lshortfile
	Lfuncname      = slog.Lfuncname
	Lshortfuncname = slog.Lshortfuncname
	LUTC           = slog.LUTC
	Llevelinitial  = slog.Llevelinitial
	Llevel         = slog.Llevel
	Lgopid         = slog.Lgopid

	Lmedfile  = slog.Lmedfile
	LstdFlags = slog.LstdFlags
)

const Ldefault = slog.Ldefault

// Flags holds a legacy-format flag set.
type Flags = slog.Flags

// Deprecated: use slog.FlagsFromBits.
func FlagsFromBits(bits uint32) Flags {
	return slog.FlagsFromBits(bits)
}

// Deprecated: use slog.FlagsFromString.
func FlagsFromString(from string, def ...uint32) Flags {
	return slog.FlagsFromString(from, def...)
}
